<script setup lang="ts">
import { label } from '../blog/siteText'
import {ref,computed,watch,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {request} from '../api'
import PrivatePreview from '../admin/PrivatePreview.vue'
const route=useRoute(),router=useRouter(),q=ref(''),year=ref(''),type=ref(''),mode=ref(''),tags=ref<string[]>([]),items=ref<any[]>([]),facets=ref<any>({years:[],types:[],tags:[]}),total=ref(0),busy=ref(false),error=ref(''),invalid=ref(false),composing=ref(false)
let generation=0,timer:ReturnType<typeof setTimeout>|undefined
const page=computed(()=>Math.max(1,Math.min(100000,Math.floor(Number(route.query.page))||1))),groups=computed(()=>{const map=new Map<string,any[]>();for(const r of items.value){const y=r.display_date.slice(0,4);map.set(y,[...(map.get(y)||[]),r])}return [...map]})
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
function sync(){const p=route.query;mode.value=['daily','travel'].includes(String(p.record_mode))?String(p.record_mode):'';invalid.value=false;q.value=String(p.q||'').slice(0,200);const y=String(p.year||'');year.value=/^\d{1,4}$/.test(y)&&Number(y)>0&&Number(y)<=9999?y:'';type.value=uuid.test(String(p.type||''))?String(p.type):'';const a=Array.isArray(p.tag)?p.tag:p.tag?[p.tag]:[];tags.value=[...new Set(a.filter((x):x is string=>typeof x==='string'&&uuid.test(x)))].slice(0,10);invalid.value=!!(y&&!year.value||p.type&&!type.value||a.length!==tags.value.length||String(p.q||'').length>200||p.page&&(!/^\d+$/.test(String(p.page))||Number(p.page)<1||Number(p.page)>100000))}
async function load(){const g=++generation;busy.value=true;error.value='';const params=new URLSearchParams({page:String(page.value)});if(q.value.trim())params.set('q',q.value.trim());if(year.value)params.set('year',year.value);if(type.value)params.set('type',type.value);if(mode.value)params.set('record_mode',mode.value);tags.value.forEach(t=>params.append('tag',t));try{const [d,f]=await Promise.all([request('/blog/archive?'+params),request('/blog/archive/facets')]);if(g!==generation)return;const last=Math.max(1,Math.ceil(d.total/20));if(page.value>last){const query={...route.query};if(last===1)delete query.page;else query.page=String(last);void router.replace({path:'/archive',query});return}items.value=d.items;total.value=d.total;facets.value=f}catch(e){if(g===generation){error.value=String(e);items.value=[];total.value=0}}finally{if(g===generation)busy.value=false}}
function apply(next=1){clearTimeout(timer);const query:any={};if(q.value.trim())query.q=q.value.trim();if(year.value)query.year=year.value;if(type.value)query.type=type.value;if(mode.value)query.record_mode=mode.value;if(tags.value.length)query.tag=tags.value;if(next>1)query.page=String(next);const nextRoute={path:'/archive',query};if(router.resolve(nextRoute).fullPath===route.fullPath)void load();else void router.push(nextRoute)}
function search(){clearTimeout(timer);generation++;busy.value=true;if(!composing.value)timer=setTimeout(()=>apply(),350)}
function clear(){q.value='';year.value='';type.value='';mode.value='';tags.value=[];apply()}
function plain(s:string){return s.replace(/<[^>]*>/g,'').replace(/[#*>`_]/g,'').trim()}
watch(()=>route.fullPath,()=>{clearTimeout(timer);sync();void load()},{immediate:true})
onUnmounted(()=>{generation++;clearTimeout(timer)})
</script>
<template><section class="archive-discovery"><header class="archive-heading"><span class="blog-kicker">THE ARCHIVE</span><h1>{{label('page.archive','生活归档')}}</h1><p>让散落的故事，重新相遇。</p></header><form class="archive-filters" @submit.prevent="apply()"><label class="archive-search">寻找一段记忆<input v-model="q" type="search" maxlength="200" placeholder="搜索标题、正文、标签或可搜索字段" @input="search" @compositionstart="composing=true" @compositionend="composing=false;search()" /></label><label>年份<select aria-label="年份" v-model="year" @change="apply()"><option value="">全部年份</option><option v-for="y in facets.years" :key="y.year" :value="String(y.year)">{{y.year}}（{{y.count}}）</option></select></label><label>内容类型<select aria-label="内容类型" v-model="type" @change="apply()"><option value="">全部类型</option><option v-for="t in facets.types" :key="t.id" :value="t.id">{{t.name}}（{{t.count}}）</option></select></label><label>记录模式<select aria-label="记录模式" v-model="mode" @change="apply()"><option value="">全部模式</option><option value="daily">日常记录</option><option value="travel">旅行记录</option></select></label><details class="archive-tag-filter"><summary>标签筛选 · 已选 {{tags.length}}</summary><p>多标签采用 AND：必须同时包含所有选中标签。数量为全站可见已发布记录数。</p><div class="tag-options"><label v-for="t in facets.tags" :key="t.id"><input v-model="tags" type="checkbox" :value="t.id" :disabled="tags.length>=10&&!tags.includes(t.id)" @change="apply()" />{{t.name}}（{{t.count}}）</label></div><p v-if="facets.tags_truncated">当前显示前 1000 个标签；可用关键词继续搜索记录。</p></details><div class="actions"><button class="blog-primary" type="submit">查找故事</button><button type="button" class="quiet" @click="clear">清空筛选</button></div></form><p v-if="invalid" role="status">部分筛选参数无效，已安全忽略。</p><p v-if="busy" role="status">正在寻找记忆…</p><p v-else-if="error" role="alert">{{error}} <button class="quiet" @click="load">重新加载</button></p><template v-else><p class="archive-count" role="status">找到 {{total}} 篇故事</p><p v-if="!total" class="blog-empty">{{q||year||type||tags.length?'没有找到匹配的故事，试试减少筛选条件。':'这里还没有已发布的故事，值得记住的生活会慢慢积累。'}}</p><section v-for="[y,records] in groups" :key="y" class="archive-year"><h2>{{y}}<small>年 · 生活切片</small></h2><div class="archive-stories"><article v-for="r in records" :key="r.id" class="archive-story"><RouterLink :to="'/posts/'+r.id" class="archive-cover" v-if="r.cover"><PrivatePreview :id="r.cover.id" :alt="r.cover.alt" /></RouterLink><div><span class="story-date">{{r.display_date}} · {{r.record_mode_name||r.type_name}}</span><h3><RouterLink :to="'/posts/'+r.id">{{r.title}}</RouterLink></h3><p>{{plain(r.excerpt)}}</p><div class="tag-pills"><RouterLink v-for="t in r.tags" :key="t.id" :to="{path:'/archive',query:{tag:t.id}}">#{{t.name}}</RouterLink></div></div></article></div></section><nav class="pagination" aria-label="归档分页"><button class="quiet" :disabled="page<=1" @click="apply(page-1)">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/20))}}</span><button class="quiet" :disabled="page*20>=total" @click="apply(page+1)">下一页</button></nav></template></section></template>
